#
# Rule:        CKV_AWS_79 (checkov 3.3.16)
# Applies to:  aws_instance, aws_launch_configuration, aws_launch_template
# Answered by: aws_compute_assets#imds_tokens_or_disabled
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_79'] || []
applies_to   = %w[aws_instance aws_launch_configuration aws_launch_template]

control 'CKV_AWS_79' do
  title 'Ensure Instance Metadata Service Version 1 is not enabled'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the instances, launch configurations and launch templates that actually
    exist.
  DESC

  desc 'rationale', <<~RATIONALE
    IMDSv1 answers an unauthenticated GET, so any server-side request
    forgery in a workload on the instance reaches the credential endpoint.
    IMDSv2 requires a PUT-issued token, which SSRF cannot forge.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_instance: metadata_options/[0]/http_tokens is
    required; aws_launch_configuration: metadata_options/[0]/http_tokens is
    required; aws_launch_template: metadata_options/[0]/http_tokens is
    required
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_instance:

      resource "aws_instance" "app" {
        ami           = var.ami_id
        instance_type = "t3.micro"

        metadata_options {
          http_endpoint = "enabled"
          http_tokens   = "required"   # IMDSv2 only
        }
      }

    Out of band — aws_instance:

      aws ec2 modify-instance-metadata-options \
        --instance-id <id> --http-tokens required --http-endpoint enabled

    Terraform — aws_launch_configuration:

      resource "aws_launch_configuration" "app" {
        name_prefix   = "app-"
        image_id      = var.ami_id
        instance_type = "t3.micro"

        metadata_options {
          http_endpoint = "enabled"
          http_tokens   = "required"
        }
      }

    Note (aws_launch_configuration): Launch configurations are immutable and
    deprecated by AWS in favour of launch templates; the fix replaces the
    configuration rather than editing it.

    Terraform — aws_launch_template:

      resource "aws_launch_template" "app" {
        name_prefix   = "app-"
        image_id      = var.ami_id
        instance_type = "t3.micro"

        metadata_options {
          http_endpoint = "enabled"
          http_tokens   = "required"
        }
      }

    Out of band — aws_launch_template:

      Create a new launch template version with the corrected metadata_options
      and update the consumers to $Latest -- a version is immutable once created.
  FIX

  tag checkov_id:       'CKV_AWS_79'
  tag checkov_category: 'GENERAL_SECURITY'
  tag checkov_version:  '3.3.16'
  tag checkov_kind:     'value'
  tag tf_resources:     %w[aws_instance aws_launch_configuration aws_launch_template]
  tag tf_argument:      'metadata_options/[0]/http_tokens'
  tag tf_docs:          'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/instance#metadata-options'
  tag nist:             ['AC-3', 'AC-6']
  tag nist_r4:          ['AC-3', 'AC-6']
  tag cci:              ['CCI-000213', 'CCI-002233']
  tag ksi:              ['KSI-IAM-MFA']
  tag severity:         'high'
  tag severity_source:  'assessed'
  tag nist_source:      'reviewed'
  tag implementation_status: 'implemented'

  assets = aws_compute_assets(regions: scan_regions)

  # Only the asset types this check declares, only what the boundary has, and
  # only those that express the setting at all — a launch template has no
  # ebs_optimized, and nil must not read as a passing false.
  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets_of(applies_to, exempt: exempt)
                   .reject { |a| a[:imds_tokens_or_disabled].nil? }

  applicable = !in_scope.empty?

  # Two statements, not a ternary: InSpec's AST impact collector calls `.value`
  # on the argument node, and a ternary is an IfNode with none — it aborts
  # `check` for the whole profile before a single control runs.
  impact 0.7
  impact 0.0 unless applicable

  only_if("no #{applies_to.join(', ')} in scope expressing this setting") { applicable }

  in_scope.each do |asset|
    describe "#{asset[:type]} #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:imds_tokens_or_disabled] }
      it { should eq true }
    end
  end
end
